#include <iostream>
using namespace std;

int main() {
    int total = 7, count = 2;
    double avg1 = total / count;
    double avg2 = (double) total / count;
    double avg3 = static_cast<double>(total) / count;
    int n = (int) 9.87;
    cout << avg1 << " " << avg2 << " " << avg3 << " " << n << endl;
    return 0;
}

#include <iostream>
using namespace std;

int main() {
    char ch = 'A';
    int code = ch;
    char next = ch + 1;
    cout << code << endl;
    cout << next << endl;
    cout << ch + 1 << endl;
    cout << (char)(ch + 2) << endl;
    cout << static_cast<int>('a') << endl;
    return 0;
}

#include <iostream>
using namespace std;

int main() {
    int m1 = 78, m2 = 85, m3 = 90;
    int sum = m1 + m2 + m3;
    double wrong = sum / 3;
    double right = static_cast<double>(sum) / 3;
    cout << "wrong = " << wrong << endl;
    cout << "right = " << right << endl;
    return 0;
}

